// This is a placeholder for the service worker that will be generated by next-pwa
// The actual service worker is generated at build time

self.addEventListener('install', (_event) => {
  self.skipWaiting()
})

self.addEventListener('activate', (event) => {
  event.waitUntil(self.clients.claim())
})

// Background sync for offline support
self.addEventListener('sync', (event) => {
  if (event.tag === 'sync-income') {
    event.waitUntil(syncIncomeData())
  }
})

async function syncIncomeData() {
  // This will be handled by the useOfflineSync hook
  // The service worker just triggers the sync event
  const clients = await self.clients.matchAll()
  clients.forEach((client) => {
    client.postMessage({ type: 'SYNC_INCOME' })
  })
}
